  const ex = nuStf().find(p => p.n === nm); if (ex) { ex.pct = pct; ex.prof = prof; } else nuStf().push({ id: 'nr' + Math.random().toString(36).slice(2, 10), n: nm, prof, pct, q: [] }); n++; }); return n; }
function nuPick(id, d) { const p = nuBy(id), W = nuW(), opts = [['B', 'בוקר'], ['E', 'ערב'], ['N', 'לילה'], ['B*', 'בוקר · אחראית'], ['E*', 'ערב · אחראית'], ['N*', 'לילה · אחראית'], ['S', 'מחלה'], ['T', 'יום עיון'], ['', 'ריק']];
